# Clear, structured goal text for every bench program: the question, the idea, the parts, the real result, what to understand.
def G(q, idea, parts, result, learn):
    h = f'<b>السؤال:</b> {q}<br><b>الفكرة:</b> {idea}'
    for lab, t in parts: h += f'<br><b>{lab}:</b> {t}'
    h += f'<br><b>النتيجة الحقيقية:</b> {result}<br><b>المطلوب تفهمه:</b> {learn}'
    return _codeify(h)

import re as _re
def _codeify(h):
    # wrap short Latin assignments like  a = 8  or  ref = b  in <code>, so they read left-to-right inside Arabic text
    parts = _re.split(r'(<code>.*?</code>|<[^>]+>)', h)
    pat = _re.compile(r'(?<![\w])([A-Za-z_*][\w\[\]()*.]*\s*=\s*‎?-?[A-Za-z0-9_]+(?:\.\d+)?)')
    rep = lambda p: pat.sub(lambda m: m.group(0) if p[max(0, m.start() - 2):m.start()].strip() in ('×', '·', '+') else f'<code>{m.group(1)}</code>', p)
    return ''.join(p if p.startswith('<') else rep(p) for p in parts)

